// ACL w infrastrukturze
internal sealed class ErpCreditCheck(ErpClient erp) : ICustomerCreditCheck
{
    public async Task<CreditLimit> GetLimitAsync(CustomerId id, CancellationToken ct)
    {
        var dto = await erp.GetKontrahentAsync(id.Value.ToString(), ct);
        return dto.STATUS == "B"
            ? CreditLimit.Blocked
            : new CreditLimit(new Money(dto.LIMIT_KR, "PLN"));
    }
}

public sealed record Money
{
    public decimal Amount { get; }
    public string Currency { get; }

    public Money(decimal amount, string currency)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        if (currency is not { Length: 3 }) throw new ArgumentException("ISO 4217");
        (Amount, Currency) = (amount, currency);
    }

    public Money Add(Money other) => other.Currency == Currency
        ? new Money(Amount + other.Amount, Currency)
        : throw new InvalidOperationException("Różne waluty");
}

