public abstract class Entity<TId> where TId : struct
{
    public TId Id { get; protected init; }
    public override bool Equals(object? o) =>
        o is Entity<TId> e && e.GetType() == GetType() && e.Id.Equals(Id);
    public override int GetHashCode() => Id.GetHashCode();
}

public sealed class Order : Entity<OrderId>
{
    private readonly List<OrderLine> _lines = [];
    public IReadOnlyCollection<OrderLine> Lines => _lines.AsReadOnly();
    public OrderStatus Status { get; private set; }

    public void AddLine(ProductId product, int qty, Money price)
    {
        if (Status != OrderStatus.Draft)
            throw new DomainException("Zamówienie jest zamknięte");
        _lines.Add(new OrderLine(product, qty, price));
    }
}

