internal sealed class OrderConfig : IEntityTypeConfiguration<Order>
{
    public void Configure(EntityTypeBuilder<Order> b)
    {
        b.HasKey(o => o.Id);
        b.Property(o => o.Id).HasConversion(id => id.Value, v => new OrderId(v));
        b.ComplexProperty(o => o.ShippingAddress);
        b.OwnsMany(o => o.Lines, l => l.WithOwner().HasForeignKey("OrderId"));
        b.Navigation(o => o.Lines).HasField("_lines");
        b.Property<byte[]>("RowVersion").IsRowVersion();
    }
}

public sealed class Order
{
    public OrderStatus Status { get; private set; }
    public decimal Total { get; private set; }

    public void Apply(OrderPlaced e) { Status = OrderStatus.Placed; Total = e.Total; }
    public void Apply(OrderPaid e) => Status = OrderStatus.Paid;

    public static Order Rehydrate(IEnumerable<object> events)
    {
        var order = new Order();
        foreach (var e in events) order.Apply((dynamic)e);
        return order;
    }
}

